package com.example.application_service.security;import com.example.application_service.exception.ApiException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.core.MethodParameter;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import org.springframework.web.bind.support.WebDataBinderFactory;import org.springframework.web.context.request.NativeWebRequest;import org.springframework.web.method.support.*;import java.util.*;
@Component public class IdentityArgumentResolver implements HandlerMethodArgumentResolver{private static final Set<String> ROLES=Set.of("CANDIDATE","EMPLOYER","ADMIN");public boolean supportsParameter(MethodParameter p){return p.getParameterType()==RequestIdentity.class;}public Object resolveArgument(MethodParameter p,ModelAndViewContainer m,NativeWebRequest w,WebDataBinderFactory b){HttpServletRequest r=w.getNativeRequest(HttpServletRequest.class);try{String role=r.getHeader("X-User-Role"),email=r.getHeader("X-User-Email");UUID id=UUID.fromString(r.getHeader("X-User-Id"));if(!ROLES.contains(role)||email==null||email.isBlank())throw new IllegalArgumentException();return new RequestIdentity(id,email,role);}catch(RuntimeException e){throw new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","Verified gateway identity is required");}}}
